// Write bitplane pointer registers into a copper list.
// BPL1PTH = $DFF0E0, each pointer pair is 4 bytes apart.
static inline USHORT* copSetPlanes(USHORT* cl, const UBYTE** planes, int n) {
    for (int i = 0; i < n; i++) {
        ULONG a = (ULONG)planes[i];
        UWORD reg = 0x00E0 + i * 4;  // BPLxPTH
        *cl++ = reg;
        *cl++ = (UWORD)(a >> 16);
        *cl++ = reg + 2;  // BPLxPTL
        *cl++ = (UWORD)a;
    }
    return cl;
}

// ========================================================================
// Entry point: take system, build copper list, display, wait for click
// ========================================================================
int main() {
    SysBase = *((struct ExecBase**)4UL);
    custom = (struct Custom*)0xdff000;
    GfxBase = (struct GfxBase*)OpenLibrary((CONST_STRPTR)"graphics.library", 0);
    if (!GfxBase) return 0;

    // Check for AGA: graphics.library v39+ only exists on A1200/A4000
    if (GfxBase->LibNode.lib_Version < 39) {
        struct Library* DOSBase = OpenLibrary((CONST_STRPTR)"dos.library", 0);
        if (DOSBase) {
            Write(Output(), (APTR)"This image requires AGA (A1200/A4000).\n", 42);
            Delay(150);
            CloseLibrary(DOSBase);
        }
        CloseLibrary((struct Library*)GfxBase);
        return 0;
    }

    TakeSystem();
    WaitVbl();

    USHORT* copper1 = (USHORT*)AllocMem(8968, MEMF_CHIP);
    USHORT* cl = copper1;

    // Data fetch start/stop — controls which horizontal pixels have bitplane data
    *cl++ = offsetof(struct Custom, ddfstrt); *cl++ = 0x0038;  // lores
    *cl++ = offsetof(struct Custom, ddfstop); *cl++ = 0x00D0;
    // Display window start/stop — visible area on screen
    *cl++ = offsetof(struct Custom, diwstrt); *cl++ = (44<<8)|0x81;  // VSTART=44, HSTART=$81
    *cl++ = offsetof(struct Custom, diwstop); *cl++ = (0x2C<<8)|0xC1;  // VSTOP=300, HSTOP=$C1 (full PAL)
    *cl++ = offsetof(struct Custom, bplcon0); *cl++ = (6<<12)/*BPU*/|(1<<9)/*COLOR*/;  // 0x6200
    *cl++ = offsetof(struct Custom, bplcon1); *cl++ = 0;  // scroll offset = 0
    *cl++ = offsetof(struct Custom, bplcon2); *cl++ = 0x0200;  // KILLEHB
    *cl++ = 0x0106; *cl++ = 0x0000;  // BPLCON3: bank 0, no LOCT

    *cl++ = offsetof(struct Custom, bpl1mod); *cl++ = 200;
    *cl++ = offsetof(struct Custom, bpl2mod); *cl++ = 200;

    const UBYTE* planes[6];
    for (int i = 0; i < 6; i++)
        planes[i] = (const UBYTE*)test_planes + 40 * i;
    cl = copSetPlanes(cl, planes, 6);

    // AGA palette: 64 colors, 2 banks
    *cl++ = 0x0106; *cl++ = 0x0000;  // bank 0
    for (int i = 0; i < 32; i++) {
        *cl++ = offsetof(struct Custom, color) + i * 2;
        *cl++ = test_palette[0 + i];
    }
    *cl++ = 0x0106; *cl++ = 0x0200;  // bank 0, LOCT=1
    for (int i = 0; i < 32; i++) {
        *cl++ = offsetof(struct Custom, color) + i * 2;
        *cl++ = test_palette_lo[0 + i];
    }
    *cl++ = 0x0106; *cl++ = 0x2000;  // bank 1
    for (int i = 0; i < 32; i++) {
        *cl++ = offsetof(struct Custom, color) + i * 2;
        *cl++ = test_palette[32 + i];
    }
    *cl++ = 0x0106; *cl++ = 0x2200;  // bank 1, LOCT=1
    for (int i = 0; i < 32; i++) {
        *cl++ = offsetof(struct Custom, color) + i * 2;
        *cl++ = test_palette_lo[32 + i];
    }
    *cl++ = 0x0106; *cl++ = 0x0000;

    // Line 0 copper changes (before display)
        { int cur_bank = 0;
        for (int s = 0; s < 4; s++) {
            UWORD reg = test_copper[0][s].reg;
            if (reg == 0xFFFF) continue;
            int bank = reg / 32;
            if (bank != cur_bank) {
                *cl++ = 0x0106;
                *cl++ = (UWORD)(bank << 13);
                cur_bank = bank;
            }
            *cl++ = offsetof(struct Custom, color) + (reg % 32) * 2;
            *cl++ = test_copper[0][s].color;
        }
        cur_bank = 0;
        for (int s = 0; s < 4; s++) {
            UWORD reg = test_copper_lo[0][s].reg;
            if (reg == 0xFFFF) continue;
            int bank = reg / 32;
            if (bank != cur_bank) {
                *cl++ = 0x0106;
                *cl++ = (UWORD)((bank << 13) | 0x0200);
                cur_bank = bank;
            } else if (s == 0) {
                *cl++ = 0x0106;
                *cl++ = (UWORD)((bank << 13) | 0x0200);
            }
            *cl++ = offsetof(struct Custom, color) + (reg % 32) * 2;
            *cl++ = test_copper_lo[0][s].color;
        }
        *cl++ = 0x0106; *cl++ = 0x0000;
        }
    // Per-scanline copper palette changes (end of previous line)
    for (int y = 1; y < 119; y++) {
        USHORT line = y - 1 + 44;
        if (line == 256) {
            *cl++ = 0xFFDF; *cl++ = 0xFFFE;  // cross 256 boundary
        }
        *cl++ = ((line & 0xFF) << 8) | 0xDF;
        *cl++ = 0xfffe;
        { int cur_bank = 0;
        for (int s = 0; s < 4; s++) {
            UWORD reg = test_copper[y][s].reg;
            if (reg == 0xFFFF) continue;
            int bank = reg / 32;
            if (bank != cur_bank) {
                *cl++ = 0x0106;
                *cl++ = (UWORD)(bank << 13);
                cur_bank = bank;
            }
            *cl++ = offsetof(struct Custom, color) + (reg % 32) * 2;
            *cl++ = test_copper[y][s].color;
        }
        cur_bank = 0;
        for (int s = 0; s < 4; s++) {
            UWORD reg = test_copper_lo[y][s].reg;
            if (reg == 0xFFFF) continue;
            int bank = reg / 32;
            if (bank != cur_bank) {
                *cl++ = 0x0106;
                *cl++ = (UWORD)((bank << 13) | 0x0200);
                cur_bank = bank;
            } else if (s == 0) {
                *cl++ = 0x0106;
                *cl++ = (UWORD)((bank << 13) | 0x0200);
            }
            *cl++ = offsetof(struct Custom, color) + (reg % 32) * 2;
            *cl++ = test_copper_lo[y][s].color;
        }
        *cl++ = 0x0106; *cl++ = 0x0000;
        }
    }

    *cl++ = (163<<8)|1; *cl++ = 0xfffe;  // WAIT line 163
    *cl++ = offsetof(struct Custom, bplcon0); *cl++ = (1<<9)/*COLOR*/;  // 0 planes, blank below image
    *cl++ = 0xffff; *cl++ = 0xfffe;

    // Turn off floppy motor (select DF0, motor off, deselect)
    *(volatile UBYTE*)0xbfd100 &= ~(1<<3);  // select DF0
    *(volatile UBYTE*)0xbfd100 |=  (1<<7);   // motor off
    *(volatile UBYTE*)0xbfd100 |=  (1<<3);   // deselect DF0

    custom->cop1lc = (ULONG)copper1;
    custom->dmacon = DMAF_BLITTER;
    custom->copjmp1 = 0x7fff;
    custom->dmacon = DMAF_SETCLR | DMAF_MASTER | DMAF_RASTER | DMAF_COPPER;

    while (!MouseLeft()) { WaitVbl(); }

    FreeSystem();
    FreeMem(copper1, 8968);
    CloseLibrary((struct Library*)GfxBase);

    // Exit message
    { struct Library* DOSBase = OpenLibrary((CONST_STRPTR)"dos.library", 0);
      if (DOSBase) {
        static const char msg[] = "\n\033[1;33m                 ___            _\n  _ __ _ _  __ _|_  )__ _ _ __ (_)__ _ __ _\n | '_ \\ ' \\/ _` |/ // _` | '  \\| / _` / _` |\n | .__/_||_\\__, /___\\__,_|_|_|_|_\\__, \\__,_|\n |_|       |___/                 |___/\n\033[0m\n  test\n  320x119, 6bpl, 64 colors, AGA 24-bit\n  28560 bytes bitplane data\n  Copper: 4 changes/line\n\n  \033[36mhttps://www.png2amiga.app\033[0m\n\n";
        BPTR fh = Output();
        if (fh) Write(fh, (APTR)msg, 358);
        CloseLibrary(DOSBase);
    } }

    return 0;
}
